const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
if (initialMs > 0) {
  ctx.on(
    audio,
    "loadedmetadata",
    () => {
      audio.currentTime = initialMs / 1000;
    },
    { once: true },
  );
}

