75			assert.ok(attrs.audioUrl, "audioUrl must be set");
76			assert.ok(attrs.nextAudioUrl, "nextAudioUrl must be set");
77			assert.ok(attrs.nextTimingsUrl, "nextTimingsUrl must be set");
78			assert.ok(attrs.nextChapterId, "nextChapterId must be set");
79			assert.notStrictEqual(
80				attrs.audioUrl,
81				attrs.nextAudioUrl,
82				"next URL must differ from current",
83			);
84			assert.ok(attrs.bookTitle, "bookTitle must be set for Media Session");
85			assert.ok(attrs.chapterTitle, "chapterTitle must be set for Media Session");
86		});
87	
88		it("Media Session metadata is registered", async (t) => {
89			if (!playerExists) {
90				t.skip("No audio-ready chapter — skipping");
91				return;
92			}
93			// Wait a tick for the hook to mount and call new MediaMetadata().
94			await sleep(200);
95			const meta = await page.evaluate(() => {
96				if (!("mediaSession" in navigator)) return null;
97				const m = navigator.mediaSession.metadata;
98				if (!m) return null;
99				return { title: m.title, artist: m.artist, album: m.album };
100			});
101			// Headless Chromium supports MediaSession; if it doesn't on a given
102			// runtime, treat as a soft skip rather than a hard failure.
103			if (meta === null) {
104				t.skip("MediaSession not available in this browser");
105				return;
106			}
107			assert.ok(meta.title?.length > 0, "Media Session title should be set");
108			assert.ok(meta.artist?.length > 0, "Media Session artist should be set");
109		});
