111		it("ended event swaps audio.src + patches URL without tearing down player", async (t) => {
112			if (!playerExists) {
113				t.skip("No audio-ready chapter — skipping");
114				return;
115			}
116	
117			// Snapshot current state.
118			const before = await page.evaluate(() => {
119				const player = document.getElementById("audio-player");
120				const audio = document.getElementById("audio-element");
121				return {
122					url: window.location.pathname + window.location.search,
123					audioSrc: audio?.src ?? null,
124					nextAudioUrl: player?.dataset.nextAudioUrl ?? null,
125					nextChapterId: player?.dataset.nextChapterId ?? null,
126					audioNodeId: audio ? audio.dataset.testId : null,
127				};
128			});
129	
130			assert.ok(before.nextAudioUrl, "must have a next audio URL to swap to");
131			assert.ok(
